use jsonlogic::{
    apply, partial_apply,
    PartialApplyOutcome::{Ambiguous, Resolved},
};
use serde_json::{json, Value};

#[test]
fn test_1() {
    let logic = json!({
      "and": [
        { ">": [{ "var": "age" }, 18] },
        { "<=": [{ "var": "age" }, 65] },
        { "==": [{ "var": "test" }, "test"] },
        {
          "or": [
            { "==": [{ "var": "status" }, "employed"] },
            { "==": [{ "var": "status" }, "student"] }
          ]
        }
      ]
    });
    assert_eq!(
        partial_apply(
            &logic,
            &json!({
              "status": "test",
            })
        ),
        Ok(Resolved(json!(false)))
    );
    assert_eq!(
        partial_apply(
            &logic,
            &json!({
              "status": "test",
            })
        ),
        apply(
            &logic,
            &json!({
              "status": "test",
            })
        )
        .map(|val| Resolved(val)),
    );
    assert_eq!(
        partial_apply(
            &logic,
            &json!({
              "status": "student",
              "test": "test",
            })
        ),
        Ok(Ambiguous)
    );
    assert_eq!(
        partial_apply(
            &logic,
            &json!({
              "status": "student",
              "test": "test",
              "age": 30
            })
        ),
        Ok(Resolved(json!(true)))
    );
    assert_eq!(
        partial_apply(
            &logic,
            &json!({
              "status": "student",
              "test": "test",
              "age": 30
            })
        ),
        apply(
            &logic,
            &json!({
              "status": "student",
              "test": "test",
              "age": 30
            })
        )
        .map(|val| Resolved(val)),
    );
}

