        test_strict_not_equal(&json!(1), &json!("1"), true);
        test_strict_not_equal(&json!([1]), &json!("1"), true);
        test_strict_not_equal(&json!([1, 2]), &json!("1,2"), true);
        test_strict_not_equal(&json!(0), &json!(null), true);
    }
}

