                .iter()
                .cloned()
                .collect::<HashSet<_>>())
        );

        assert_eq!(
            Expression::Computed(
                Operator::And,
                vec![
                    Expression::Computed(
                        Operator::Equal,
                        vec![
                            Expression::Computed(
                                Operator::Variable,
                                vec![Expression::Constant(&json!("foo"))]
                            ),
                            Expression::Constant(&json!(2))
                        ]
                    ),
                    Expression::Computed(
                        Operator::Equal,
